import{_ as i,o as a,c as t,a2 as e}from"./chunks/framework.hwbV7reR.js";const c=JSON.parse('{"title":"Проверки выпуска","description":"","frontmatter":{},"headers":[],"relativePath":"release-security.md","filePath":"release-security.md","lastUpdated":1791695486000}'),n={name:"release-security.md"};function p(h,s,r,l,k,o){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="проверки-выпуска" tabindex="-1">Проверки выпуска <a class="header-anchor" href="#проверки-выпуска" aria-label="Permalink to &quot;Проверки выпуска&quot;">​</a></h1><p>Перед публикацией тега выполняются тесты на Python 3.12, 3.13 и 3.14, проверка архитектуры, типов, форматирования, контрактов, секретов и известных уязвимостей runtime-зависимостей. Конкретный запуск матрицы подтверждает GitHub Actions; локальная проверка одной версии Python не подтверждает остальные.</p><h2 id="зависимости-и-секреты" tabindex="-1">Зависимости и секреты <a class="header-anchor" href="#зависимости-и-секреты" aria-label="Permalink to &quot;Зависимости и секреты&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements-security.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check_secrets.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip_audit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements.lock</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-deps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --disable-pip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check_workflows.py</span></span></code></pre></div><p><code>pip-audit</code> обращается к публичной базе PyPI и передаёт названия и версии пакетов. Ошибка проверки блокирует выпуск; исключений CVE по умолчанию нет. Это проверка закреплённых runtime-зависимостей, не полный аудит системы, dev/npm-зависимостей или собственного кода. Отсутствие известных CVE не доказывает безопасность. <a href="https://github.com/pypa/pip-audit" target="_blank" rel="noreferrer">Документация инструмента</a>.</p><p><code>detect-secrets</code> используется офлайн, без проверки найденных ключей через внешние сервисы. Сканируются отслеживаемые Git файлы текущего снимка, не история коммитов. Вывод содержит только путь, тип и отпечаток кандидата. Новая находка блокирует выпуск. В <code>contracts/secret-baseline.json</code> перечислены проверенные отпечатки синтетических тестовых значений, алфавита генератора ID и контрольных сумм закреплённого агента. Не добавляйте новую находку автоматически: сначала установите её происхождение. Не сохраняйте реальные секреты под видом исключения.</p><p>Все внешние GitHub Actions закреплены на commit SHA. Dependabot предлагает обновления Actions, pip и npm; изменения всё равно требуют проверки. Сторонние зависимости инструментов анализа загружаются из реестра: полная фиксация их транзитивных хешей и защита веток GitHub остаются отдельными задачами сопровождения.</p><h2 id="происхождение-архива" tabindex="-1">Происхождение архива <a class="header-anchor" href="#происхождение-архива" aria-label="Permalink to &quot;Происхождение архива&quot;">​</a></h2><p>Release job запускается только после verify, проверяет соответствие тега VERSION и собирает архив из точного Git-коммита. Он не включает runtime-журналы или настройки. Gzip timestamp фиксирован: повторная упаковка одного коммита даёт те же байты.</p><p>Перед публикацией <code>actions/attest</code> создаёт GitHub/Sigstore attestation для <code>.tar.gz</code>. Права записи и OIDC есть только у release job. При отказе attestation публикация не выполняется. Это подтверждает происхождение артефакта, а не качество его исходников. <a href="https://docs.github.com/en/actions/how-tos/secure-your-work/use-artifact-attestations/use-artifact-attestations" target="_blank" rel="noreferrer">Механизм GitHub</a>.</p><p>Скачанный архив проверьте перед запуском установщика/обновления:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attestation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> undercore-orchestrator-vX.Y.Z.tar.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UndercoreCo/orchestrator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --signer-workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UndercoreCo/orchestrator/.github/workflows/release.yml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shasum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 256</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS</span></span></code></pre></div><p>Updater по-прежнему проверяет содержимое, checksum, совместимость и миграцию; сам он не запрашивает GitHub attestation. Проверка выше — отдельный шаг оператора. Старые выпуски без attestation не получают её задним числом. Первое реальное подтверждение этой цепочки появится после успешного выпуска через новый workflow.</p>`,13)])])}const F=i(n,[["render",p]]);export{c as __pageData,F as default};
